-- Provides route-step text, shared runtime-step lookup, progression and coordinate/zone interpretation.
-- GetStep owns the runtime copy; consumers must not mutate nested route-definition tables.

local L = LibStub("AceLocale-3.0"):GetLocale("APR")

-- Primary and secondary keys that identify the main action for a step.
-- Keeping them here ensures other modules can reason about step intent without re-declaring lists.
APR.mainStepOptions = {
    "KillNPC",
    "ExitTutorial", "PickUp", "PickUpDB", "DropQuest", "Qpart", "QpartDB", "QpartPart", "Treasure", "Group", "Done",
    "DoneDB", "Scenario", "EnterInstance", "LeaveInstance", "EnterScenario", "DoScenario", "LeaveScenario", "SetHS",
    "UseHS", "UseDalaHS", "UseGarrisonHS", "UseItem", "UseSpell", "GetFP", "UseFlightPath", "TakePortal",
    "LearnProfession", "LootItems", "WarMode", "Grind", "Reputation", "LootMoney", "Emote", "Achievement",
    "RouteCompleted", "Note", "DeathSkip", "SellItems", "LearnSkill", "BankDeposit", "BankWithdraw", "TameBeast",
    "DestroyItems", "EquipItem", "Repair", "LeaveQuest", "LeaveQuests", "ResetRoute", "Zeppelin", "Boat", "Tram"
}

-- BuyMerchant need to be first
APR.secondaryStepOptions = {
    "BuyMerchant", "GossipOptionIDs", "GroupTask", "ChromiePick",
    "MountVehicle", "VehicleExit"
}

-- Flights with an arrival trigger poll destination completion like other transports.
-- Flight steps without a trigger retain their legacy departure/quest behavior.
function APR:IsTransportStep(step)
    return step and step.ZoneStepTrigger and (step.UseFlightPath or step.Waypoint or step.Zeppelin or step.Boat or step.Tram)
        and not step.TakePortal
end--[[APR_DIAG]]; APR.IsTransportStep = APRTrace("APR-Core/utils/StepUtils.lua:31:APR:IsTransportStep#1", APR.IsTransportStep)--[[/APR_DIAG]]

function APR:GetTransportStepText(step)
    local trigger = step.TakePortal or step.ZoneStepTrigger or {}
    local mapInfo = trigger.mapID and self:GetMapInfoCached(trigger.mapID)
    local destination = (mapInfo and mapInfo.name) or step.Name or UNKNOWN
    if step.NodeID or step.UseFlightPath then
        local nodeName = self:GetTaxiNodeName(step)
        if nodeName ~= UNKNOWN then destination = nodeName end
    end
    if step.Waypoint then return L["WAYPOINT"], "Waypoint" end
    if step.UseFlightPath and not (step.Boat or step.Zeppelin or step.Tram) then
        local text = string.format(L["USE_FLIGHTPATH"], destination)
        local flight = self.flightPath
        if flight and flight.unavailableNodes and flight.unavailableNodes[step.NodeID] then
            text = text .. "\n" .. L["FLIGHT_PATH_UNAVAILABLE"]
        end
        return text, "UseFlightPath"
    end
    if step.TakePortal and not (step.Boat or step.Zeppelin or step.Tram) then
        return string.format(L["USE_PORTAL_TO"], destination), "TakePortal"
    end
    if step.Tram then return L["ENTER_TRAM"] .. " - " .. destination, "Tram" end
    local kind = step.Zeppelin and "Zeppelin" or "Boat"
    return string.format(L[step.Zeppelin and "USE_ZEPPELIN_TO" or "USE_BOAT"], destination), kind
end--[[APR_DIAG]]; APR.GetTransportStepText = APRTrace("APR-Core/utils/StepUtils.lua:36:APR:GetTransportStepText#2", APR.GetTransportStepText)--[[/APR_DIAG]]

function APR:GetFlightPathDiscoveryText(step)
    local name = self:GetTaxiNodeName(step)
    return name ~= UNKNOWN and (L["GET_FLIGHTPATH"] .. " - " .. name) or L["GET_FLIGHTPATH"]
end--[[APR_DIAG]]; APR.GetFlightPathDiscoveryText = APRTrace("APR-Core/utils/StepUtils.lua:61:APR:GetFlightPathDiscoveryText#3", APR.GetFlightPathDiscoveryText)--[[/APR_DIAG]]

-- Location after a teleport is not the player's current location. Treat those
-- predicates as unknown while still rejecting definite class/faction/etc. failures.
-- Preserve unknown through Not/AnyOf/AllOf instead of inverting it into a skip.
local function ApplicableAfterTravel(self, conditions)
    local base, uncertain = {}, false
    for key, value in pairs(conditions) do
        if key == "Zones" or key == "OnlyInZones" or key == "SkipInZones" then
            uncertain = true
        elseif key ~= "AnyOf" and key ~= "AllOf" and key ~= "Not" then
            base[key] = value
        end
    end
    if self.StepFilterQoL and not self:StepFilterQoL(base) then return false end
    for _, child in ipairs(conditions.AllOf or {}) do
        local result = ApplicableAfterTravel(self, child)
        if result == false then return false end
        if result == nil then uncertain = true end
    end
    if conditions.AnyOf then
        local matched, unknown = false, false
        for _, child in ipairs(conditions.AnyOf) do
            local result = ApplicableAfterTravel(self, child)
            if result == true then matched = true end
            if result == nil then unknown = true end
        end
        if not matched and not unknown then return false end
        if not matched then uncertain = true end
    end
    if conditions.Not then
        local result = ApplicableAfterTravel(self, conditions.Not)
        if result == true then return false end
        if result == nil then uncertain = true end
    end
    if uncertain then return nil end
    return true
end--[[APR_DIAG]]; ApplicableAfterTravel = APRTrace("APR-Core/utils/StepUtils.lua:69:ApplicableAfterTravel#4", ApplicableAfterTravel)--[[/APR_DIAG]]

-- Read-only lookahead: do not run progression handlers or mutate the runtime step.
function APR:GetNextApplicableStep(steps, index)
    if not steps or not index then return nil end
    for nextIndex = index + 1, #steps do
        local candidate = steps[nextIndex]
        if ApplicableAfterTravel(self, candidate) ~= false and
            not (self.IsSojournerSkipActive and self:IsSojournerSkipActive() and self:IsStepCampaignQuest(candidate)) then
            return candidate, nextIndex
        end
    end
end--[[APR_DIAG]]; APR.GetNextApplicableStep = APRTrace("APR-Core/utils/StepUtils.lua:104:APR:GetNextApplicableStep#5", APR.GetNextApplicableStep)--[[/APR_DIAG]]

-- A bind name is a subzone, not necessarily the zone's display name. Use the
-- bundled travel data to resolve its world position, then compare map ancestry.
-- Missing data must leave the instruction generic rather than endorse a wrong bind.
function APR:GetHearthstoneStepText(nextStep)
    local text = L["USE_HEARTHSTONE"]
    if not nextStep or not (nextStep.Zone or nextStep.Zones) or not GetBindLocation then return text end
    local bindName = GetBindLocation()
    if not bindName or bindName == "" then return text end
    -- Do not include a transport's arrival trigger: the next action starts in its Zone.
    local zones = self:GetStepZoneList({ Zone = nextStep.Zone, Zones = nextStep.Zones })
    local data = self.NavigationData
    local bindMapID = data and data.GetBindLocationMapID and data:GetBindLocationMapID()
    local expectedNames, comparable = {}, bindMapID ~= nil
    local bindInfo = bindMapID and self:GetMapInfoCached(bindMapID)
    -- A continent-only result cannot establish which zone contains the bind.
    if not bindInfo or (bindInfo.mapType and bindInfo.mapType <= 2) then comparable = false end
    for _, zone in ipairs(zones) do
        local zoneInfo = self:GetMapInfoCached(zone)
        if zoneInfo and zoneInfo.name then
            expectedNames[#expectedNames + 1] = zoneInfo.name
        else
            comparable = false
        end
        local mapID, seen = bindMapID, {}
        while mapID and mapID ~= 0 and not seen[mapID] do
            if mapID == zone then return text .. " - " .. bindName end
            seen[mapID] = true
            local info = self:GetMapInfoCached(mapID)
            if not info then comparable = false end
            mapID = info and info.parentMapID
        end
        if mapID and seen[mapID] then comparable = false end
        -- Also support binds whose name is the zone itself without library data.
        if not bindMapID then
            local info = self:GetMapInfoCached(zone)
            if info and info.name == bindName then return text .. " - " .. bindName end
        end
    end
    if comparable and #expectedNames > 0 then
        return text .. "\n" .. string.format(L["HS_BIND_MISMATCH"], bindName, table.concat(expectedNames, ", "))
    end
    return text
end--[[APR_DIAG]]; APR.GetHearthstoneStepText = APRTrace("APR-Core/utils/StepUtils.lua:118:APR:GetHearthstoneStepText#6", APR.GetHearthstoneStepText)--[[/APR_DIAG]]

function APR:IsZoneStepTriggerReached(trigger, playerX, playerY)
    if not trigger then return false end
    if trigger.mapID and C_Map.GetBestMapForUnit("player") ~= trigger.mapID
        and self:GetPlayerParentMapID() ~= trigger.mapID then return false end
    -- Map-only arrivals are used by flights; their handler also waits for landing.
    if trigger.x == nil and trigger.y == nil and trigger.Range == nil then
        return trigger.mapID ~= nil
    end
    if playerX == nil or playerY == nil then
        playerY, playerX = UnitPosition("player")
    end
    if playerX == nil or playerY == nil then return false end
    return (playerX - trigger.x) ^ 2 + (playerY - trigger.y) ^ 2 < trigger.Range ^ 2
end--[[APR_DIAG]]; APR.IsZoneStepTriggerReached = APRTrace("APR-Core/utils/StepUtils.lua:159:APR:IsZoneStepTriggerReached#7", APR.IsZoneStepTriggerReached)--[[/APR_DIAG]]

function APR:GetDropQuestStepText(step)
