    local names = APRData and APRData.NPCList
    local name = (names and names[data.MobId or 1]) or data.Text or UNKNOWN
    return string.format(L["Q_DROP"], name)
end--[[APR_DIAG]]; APR.GetDropQuestStepText = APRTrace("APR-Core/utils/StepUtils.lua:174:APR:GetDropQuestStepText#8", APR.GetDropQuestStepText)--[[/APR_DIAG]]

--- Return the localized label for the first recognized step key.
-- This keeps UI construction simple while letting steps remain data-driven.
-- skipNote lets waypoint summaries prefer destination actions over notes.
function APR:GetStepString(step, skipNote, nextStep)
    if self:IsTransportStep(step) then return self:GetTransportStepText(step) end
    if step and step.LootMoney then
        return self:GetLootMoneyStepText(step.LootMoney), "LootMoney"
    end
    for _, key in ipairs(self.routeActionKeys or {}) do
        if step and step[key] then return self:GetRouteActionText(key, step[key]), key end
    end
    if not skipNote and step and step.Note then
        local noteValue = step.Note
        if type(noteValue) == "table" then
            noteValue = noteValue[1]
        end

        if noteValue ~= nil then
            local formatted = APR:ResolveStepText(noteValue)
            if formatted and formatted ~= "" then
                return formatted, "Note"
            end
        end

        if type(step.Note) == "string" and step.Note ~= "" then
            return step.Note, "Note"
        end
        return "Note", "Note"
    end

    if step and step.Reputation then
        return self:GetReputationStepText(step.Reputation), "Reputation"
    end
    if step and step.Emote then
        return string.format(L["PERFORM_EMOTE"], step.Emote.emote), "Emote"
    end

    local stepMappings = {
        KillNPC = BOSS,
        BuyMerchant = L["BUY"],
        Done = L["TURN_IN_Q"],
        DoneDB = L["TURN_IN_Q"],
        DoScenario = L["SCENARIO"],
        DropQuest = L["Q_DROP"],
        EnterInstance = INSTANCE,
        EnterScenario = L["SCENARIO"],
        ExitTutorial = L["SKIP_TUTORIAL"],
        GetFP = L["GET_FLIGHTPATH"],
        Achievement = "ACHIEVEMENTS",
        GossipOptionIDs = L["TALK_NPC"],
        Grind = L["GRIND"],
        Group = L["GROUP_Q"],
        GroupTask = L["GROUP_QUEST_TASK"],
        LeaveQuest = L["LEAVE_QUEST"],
        LeaveQuests = L["LEAVE_QUEST"],
        ChromiePick = L["SWITCH_TO_CHROMIE"],
        ResetRoute = L["RESET_ROUTE"],
        MountVehicle = L["MOUNT_VEHICLE"],
        VehicleExit = L["LEAVE_VEHICLE"],
        LearnProfession = L["LEARN_PROFESSION"],
        LeaveInstance = L["LEAVE_INSTANCE"],
        LeaveScenario = L["SCENARIO"],
        LootItems = L["LOOT_ITEM"],
        PickUp = L["PICK_UP_Q"],
        PickUpDB = L["PICK_UP_Q"],
        Qpart = L["Q_PART"],
        QpartDB = L["Q_PART"],
        QpartPart = L["Q_PART"],
        RouteCompleted = L["ROUTE_COMPLETED"],
        Scenario = L["SCENARIO"],
        SetHS = L["SET_HEARTHSTONE"],
        Treasure = L["GET_TREASURE"],
        TakePortal = L["USE_PORTAL"],
        UseDalaHS = L["USE_DALARAN_HEARTHSTONE"],
        UseFlightPath = L["USE_FLIGHTPATH"],
        UseGarrisonHS = L["USE_GARRISON_HEARTHSTONE"],
        UseHS = L["USE_HEARTHSTONE"],
        UseItem = L["USE_ITEM"],
        UseSpell = L["USE_SPELL"],
        WarMode = L["TURN_ON_WARMODE"],
        Waypoint = L["RUN_WAYPOINT"],
    }

    -- Resolve primary actions before companion fields, regardless of table order.
    for _, keys in ipairs({ self.mainStepOptions, { "Waypoint" }, self.secondaryStepOptions }) do
        for _, key in ipairs(keys) do
            if step[key] and stepMappings[key] then
                if key == "GetFP" then return self:GetFlightPathDiscoveryText(step), key end
                if key == "DropQuest" then return self:GetDropQuestStepText(step), key end
                if key == "UseHS" then return self:GetHearthstoneStepText(nextStep), key end
                if key == "UseFlightPath" or key == "TakePortal" then
                    return self:GetTransportStepText(step)
                end
                if key == "Grind" then return self:GetGrindStepText(step.Grind), key end
                if key == "UseItem" then
                    return string.format(stepMappings[key], C_Item.GetItemInfo(step.UseItem.itemID) or UNKNOWN), key
                end
                if key == "UseSpell" then
                    return string.format(stepMappings[key], self:GetSpellName(step.UseSpell.spellID) or UNKNOWN), key
                end
                if key == "LootItems" then return self:GetLootItemsStepText(step.LootItems), key end
                if key == "LeaveInstance" then
                    local rule = step.LeaveInstance
                    if rule.dungeonKey then return self:GetDungeonTravelText(step), key end
                    local info = rule.mapID and self:GetMapInfoCached(rule.mapID)
                    return string.format(stepMappings[key], info and info.name or UNKNOWN), key
                end
                if key == "GroupTask" then
                    return string.format(stepMappings[key], tostring(step.GroupTask) .. " - " ..
                        (self:GetQuestTitle(step.GroupTask) or UNKNOWN)), key
                end
                if key == "ChromiePick" then
                    local info = C_ChromieTime and C_ChromieTime.GetChromieTimeExpansionOption and
                        C_ChromieTime.GetChromieTimeExpansionOption(step.ChromiePick)
                    return string.format(stepMappings[key], info and info.name or
                        (UNKNOWN .. " (" .. step.ChromiePick .. ")")), key
                end
                return stepMappings[key], key
            end
        end
    end

    return ''
end--[[APR_DIAG]]; APR.GetStepString = APRTrace("APR-Core/utils/StepUtils.lua:184:APR:GetStepString#9", APR.GetStepString)--[[/APR_DIAG]]

function APR:GetLootItemsStepText(items)
    local names = {}
    for _, item in ipairs(items) do
        names[#names + 1] = C_Item.GetItemInfo(item.itemID) or UNKNOWN
    end
    return string.format(L["LOOT_ITEM"], table.concat(names, ", "))
end--[[APR_DIAG]]; APR.GetLootItemsStepText = APRTrace("APR-Core/utils/StepUtils.lua:306:APR:GetLootItemsStepText#10", APR.GetLootItemsStepText)--[[/APR_DIAG]]

--- Build the waypoint summary text by scanning upcoming steps for actionable instructions.
-- Notes are a fallback only when no upcoming action can describe the destination.
function APR:CheckWaypointText()
    local currentStepIndex = APRData[APR.PlayerID][APR.ActiveRoute]
    local noteText

    local function IsInList(value, list)
        for _, v in ipairs(list) do
            if v == value then
                return true
            end
        end
        return false
    end--[[APR_DIAG]]; IsInList = APRTrace("APR-Core/utils/StepUtils.lua:320:IsInList#12", IsInList)--[[/APR_DIAG]]

    local steps = APR:GetRouteSteps(APR.ActiveRoute)
    for i = currentStepIndex, #steps do
        local step = steps[i]

        if step then
            local nextStep = step.UseHS and self:GetNextApplicableStep(steps, i)
            local stepText, stepKey = APR:GetStepString(step, true, nextStep)

            if stepKey then
                if IsInList(stepKey, APR.mainStepOptions) then
                    return "[" .. L["WAYPOINT"] .. "] - " .. stepText
                elseif not step["Waypoint"] and IsInList(stepKey, APR.secondaryStepOptions) then
                    return "[" .. L["WAYPOINT"] .. "] - " .. stepText
                end
            end

            if not noteText and step.Note then
                noteText = APR:GetStepString({ Note = step.Note })
            end
        end
    end

    if noteText then
        return "[" .. L["WAYPOINT"] .. "] - " .. noteText
    end

    return L["TRAVEL_TO"] .. " - " .. L["WAYPOINT"]
end--[[APR_DIAG]]; APR.CheckWaypointText = APRTrace("APR-Core/utils/StepUtils.lua:316:APR:CheckWaypointText#11", APR.CheckWaypointText)--[[/APR_DIAG]]

--- Extract all quest IDs from a step, regardless of its type.
--- Handles every primary step format: arrays (PickUp, Done), dict keys (Qpart, QpartPart),
--- scalars (Waypoint, DropQuest, …), nested tables (.questID ),
--- and item arrays (BuyMerchant, LootItems).
---@param step table the step table from the route definition
---@return number[] questIDs flat array of numeric quest IDs (may be empty)
function APR:GetStepQuestIDs(step)
    if not step then return {} end
    local ids = {}

    -- Array keys: value is { questID1, questID2, … }
    for _, key in ipairs({ "PickUp", "Done" }) do
        local val = step[key]
        if val then
            for _, q in ipairs(val) do
                local n = tonumber(q)
                if n then ids[#ids + 1] = n end
            end
            return ids
        end
    end

    -- Dict keys: quest ID is the table key  { [questID] = { objectives } }
    for _, key in ipairs({ "Qpart", "QpartPart" }) do
        local val = step[key]
        if val then
            for q in pairs(val) do
                local n = tonumber(q)
                if n then ids[#ids + 1] = n end
            end
            return ids
        end
    end

    -- Scalar keys: value IS the quest ID
    for _, key in ipairs({ "Waypoint", "DropQuest", "ExitTutorial", "SetHS", "UseHS", "UseDalaHS", "UseGarrisonHS", "UseFlightPath", "WarMode" }) do
        local val = step[key]
        if val then
            local n = tonumber(val)
            if n then ids[#ids + 1] = n end
            return ids
        end
    end

    -- Nested .questID (lowercase)
    for _, key in ipairs({ "Treasure", "TakePortal", "UseItem", "UseSpell", "EnterScenario", "DoScenario", "LeaveScenario", "EnterInstance", "LeaveInstance", "Scenario", "Group", "SellItems" }) do
        local sub = step[key]
        if sub and sub.questID then
            local n = tonumber(sub.questID)
            if n then ids[#ids + 1] = n end
            return ids
        end
    end

    -- Array of items with .questID: BuyMerchant, LootItems
    for _, key in ipairs({ "BuyMerchant", "LootItems" }) do
        local items = step[key]
        if items then
            for _, item in ipairs(items) do
                local n = tonumber(item.questID)
                if n then ids[#ids + 1] = n end
            end
            if #ids > 0 then return ids end
        end
    end

    return ids
end--[[APR_DIAG]]; APR.GetStepQuestIDs = APRTrace("APR-Core/utils/StepUtils.lua:364:APR:GetStepQuestIDs#13", APR.GetStepQuestIDs)--[[/APR_DIAG]]

--- Quick check for primary actions, optionally excluding the action being handled.
function APR:HasAnyMainStepOption(step, excludedKeys)
    if not step then return false end
    for _, key in ipairs(APR.mainStepOptions) do
        if step[key] ~= nil and not (excludedKeys and excludedKeys[key]) then
            return true
        end
    end
    return false
end--[[APR_DIAG]]; APR.HasAnyMainStepOption = APRTrace("APR-Core/utils/StepUtils.lua:428:APR:HasAnyMainStepOption#14", APR.HasAnyMainStepOption)--[[/APR_DIAG]]

--- Call an achievement criteria API without letting stale route data raise a Lua error.
---@return boolean success
---@return string|nil criteriaLabel
---@return boolean|nil criteriaCompleted
---@return number|nil criteriaID
local function QueryAchievementCriteriaInfo(criteriaAPI, ...)
    local results = { --[[APR_DIAG]]APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](criteriaAPI, ...) }
    if not results[1] then
        return false
    end

    -- pcall adds its success flag before the regular API return values.
    return true, results[2], results[4], results[11]
end--[[APR_DIAG]]; QueryAchievementCriteriaInfo = APRTrace("APR-Core/utils/StepUtils.lua:443:QueryAchievementCriteriaInfo#15", QueryAchievementCriteriaInfo)--[[/APR_DIAG]]

--- Resolve achievement criteria by its stable ID, with index support for older route data.
---@param achievementData table|nil
---@return string|nil criteriaLabel
---@return boolean|nil criteriaCompleted
---@return number|nil criteriaID
function APR:GetAchievementCriteriaInfo(achievementData)
    local achievementID = achievementData and achievementData.achievementID
    if not achievementID then
        return nil, nil, nil
    end

    if achievementData.criteriaID and GetAchievementCriteriaInfoByID then
        local success, criteriaLabel, criteriaCompleted, criteriaID =
            QueryAchievementCriteriaInfo(GetAchievementCriteriaInfoByID, achievementID, achievementData.criteriaID)
        if success then
            return criteriaLabel, criteriaCompleted, criteriaID
        end

        -- Do not fall back to an index here: Blizzard may have removed or reordered
        -- this criterion, in which case the index can refer to a different objective.
        return nil, nil, nil
    end

    if not achievementData.criteriaIndex or not GetAchievementCriteriaInfo then
        return nil, nil, nil
    end

    local success, criteriaLabel, criteriaCompleted, criteriaID =
        QueryAchievementCriteriaInfo(GetAchievementCriteriaInfo, achievementID, achievementData.criteriaIndex)
    if success then
        return criteriaLabel, criteriaCompleted, criteriaID
    end

    -- Some achievements contain hidden criteria which are not counted by default.
    success, criteriaLabel, criteriaCompleted, criteriaID =
        QueryAchievementCriteriaInfo(GetAchievementCriteriaInfo, achievementID, achievementData.criteriaIndex, true)
    if success then
        return criteriaLabel, criteriaCompleted, criteriaID
    end

    return nil, nil, nil
end--[[APR_DIAG]]; APR.GetAchievementCriteriaInfo = APRTrace("APR-Core/utils/StepUtils.lua:458:APR:GetAchievementCriteriaInfo#16", APR.GetAchievementCriteriaInfo)--[[/APR_DIAG]]

--- Evaluate if an achievement step is complete based on achievement/criteria state.
-- Returns completion state plus a display label for UI.
-- @return boolean isCompleted
-- @return string progressText
function APR:IsAchievementStepComplete(step)
    local achievementData = step and step.Achievement
    local achievementID = achievementData and achievementData.achievementID
    local fallbackLabel = "ACHIEVEMENTS" .. ":" .. tostring(achievementID)
    if not achievementID then
        return false, fallbackLabel
    end


    if not GetAchievementInfo then
        return false, fallbackLabel
    end

    local _, achievementName, _, achievementCompleted = GetAchievementInfo(achievementID)
    local progressText = achievementName or fallbackLabel

    if achievementCompleted then
        return achievementCompleted, progressText
    end

    if achievementData.criteriaID or achievementData.criteriaIndex then
        local criteriaLabel, criteriaCompleted = APR:GetAchievementCriteriaInfo(achievementData)
        if criteriaLabel then
            progressText = criteriaLabel
        end
        return criteriaCompleted == true, progressText
    end

    return achievementCompleted, progressText
end--[[APR_DIAG]]; APR.IsAchievementStepComplete = APRTrace("APR-Core/utils/StepUtils.lua:500:APR:IsAchievementStepComplete#17", APR.IsAchievementStepComplete)--[[/APR_DIAG]]

