--- Manually skip to the next visible step.
function APR:SkipQuestStep()
    local userData = APRData[APR.PlayerID]
    local activeRoute = APR.ActiveRoute

    if not userData or not activeRoute then
        return
    end

    local questStepList = self:GetRouteSteps(activeRoute)
    local currentIndex = tonumber(userData[activeRoute]) or 1
    if currentIndex < 1 then
        currentIndex = 1
    end

    local targetIndex = currentIndex
    local tries = 0

    while targetIndex < (#questStepList + 1) do
        targetIndex = targetIndex + 1
        local step = questStepList[targetIndex]

        if not step then
            break
        end

        -- Waypoints are authored steps too: a manual skip must stop on the
        -- next visible one, including protected arrival checkpoints.
        if not self:StepFilterQuestHandler(step) then
            break
        end

        tries = tries + 1
        if tries > 100 then
            break
        end
    end

    return self:CommitManualSkip(targetIndex)
end--[[APR_DIAG]]; APR.SkipQuestStep = APRTrace("APR-Core/utils/StepUtils.lua:558:APR:SkipQuestStep#22", APR.SkipQuestStep)--[[/APR_DIAG]]

-- Rollback first reverses a valid manual skip, including its immediate automatic advances.
-- Otherwise it walks back to the preceding visible non-waypoint step.
function APR:PreviousQuestStep()
    if self:CanUndoManualSkip() then return self:UndoManualSkip() end
    local context = self:CaptureStepContext()
    if not context.route or not context.index then return false end
    local steps = self:GetRouteSteps(context.route)
    local target = math.max(1, context.index - 1)
    while target > 1 do
        local step = steps[target]
        if step and not (self:StepFilterQuestHandler(step) or step.Waypoint) then break end
        target = target - 1
    end
    return self:TransitionStep(target, "manual_previous", "quests", context)
end--[[APR_DIAG]]; APR.PreviousQuestStep = APRTrace("APR-Core/utils/StepUtils.lua:600:APR:PreviousQuestStep#23", APR.PreviousQuestStep)--[[/APR_DIAG]]

--- Lookup helpers ---------------------------------------------------------

-- Return a shallow runtime copy and the effective route list. Navigation may change
-- top-level fields on the copy; nested route data must remain read-only.
function APR:GetStep(index)
    if (index and APR.RouteQuestStepList and APR.RouteQuestStepList[APR.ActiveRoute]) then
        local steps = self:GetRouteSteps(APR.ActiveRoute)
        local source = steps[index]
        if not source then return nil end
        -- Navigation adjusts Coord/NoArrow for scenarios. Share a runtime copy
        -- with the arrow and event handlers, preserving the route fingerprint.
        local cached = self.runtimeRouteStep
        if not cached or cached.source ~= source or cached.route ~= self.ActiveRoute or cached.index ~= index then
            local step = {}
            for key, value in pairs(source) do step[key] = value end
            cached = { source = source, route = self.ActiveRoute, index = index, step = step }
            self.runtimeRouteStep = cached
        end
        return cached.step, steps
    end
    return nil
end--[[APR_DIAG]]; APR.GetStep = APRTrace("APR-Core/utils/StepUtils.lua:618:APR:GetStep#24", APR.GetStep)--[[/APR_DIAG]]

-- Resolve progress once for events, navigation and UI; startup/no route returns nil.
-- Consumers share GetStep's runtime copy instead of changing the saved route definition.
function APR:GetCurrentStep()
    local progress = APRData and APRData[self.PlayerID]
    local index = progress and self.ActiveRoute and progress[self.ActiveRoute]
    if not index then return nil end
    local step, steps = self:GetStep(index)
    return step, index, steps
end--[[APR_DIAG]]; APR.GetCurrentStep = APRTrace("APR-Core/utils/StepUtils.lua:639:APR:GetCurrentStep#25", APR.GetCurrentStep)--[[/APR_DIAG]]

-- Diagnostics must not activate parallel groups or initialize route action state.
function APR:PeekCurrentStep()
    local progress = APRData and APRData[self.PlayerID]
    local route = self.ActiveRoute
    local index = progress and route and progress[route]
    if not index then return nil end
    local runtime = self.runtimeRouteStep
    if runtime and runtime.route == route and runtime.index == index then return runtime.step, index end
    local cached = self._effectiveRouteStepsCache and self._effectiveRouteStepsCache[route]
    if cached then return cached.steps[index], index end
    local data = self.RouteQuestStepList and self.RouteQuestStepList[route]
    return data and (data.steps or data)[index], index
end--[[APR_DIAG]]; APR.PeekCurrentStep = APRTrace("APR-Core/utils/StepUtils.lua:648:APR:PeekCurrentStep#26", APR.PeekCurrentStep)--[[/APR_DIAG]]

local function NormalizeZoneList(value)
    if value == nil then
        return nil
    end

    if type(value) ~= "table" then
        return { value }
    end

    if #value > 0 then
        return value
    end

    local list = {}
    for _, zone in pairs(value) do
        table.insert(list, zone)
    end
    return list
end--[[APR_DIAG]]; NormalizeZoneList = APRTrace("APR-Core/utils/StepUtils.lua:661:NormalizeZoneList#27", NormalizeZoneList)--[[/APR_DIAG]]

--- Normalize a step's zone definition into a list, falling back to the route map id.
function APR:GetStepZoneList(step, fallbackMapID)
    local zones = step and NormalizeZoneList(step.Zones) or nil
    if not zones or #zones == 0 then
        zones = step and NormalizeZoneList(step.Zone) or nil
    end
    if not zones or #zones == 0 then
        zones = NormalizeZoneList(fallbackMapID)
    end

    if self:IsTransportStep(step) and step.ZoneStepTrigger.mapID then
        local result = {}
        for _, zone in ipairs(zones or {}) do
            if zone ~= step.ZoneStepTrigger.mapID then result[#result + 1] = zone end
        end
        result[#result + 1] = step.ZoneStepTrigger.mapID
        return result
    end
    return zones or {}
end--[[APR_DIAG]]; APR.GetStepZoneList = APRTrace("APR-Core/utils/StepUtils.lua:682:APR:GetStepZoneList#28", APR.GetStepZoneList)--[[/APR_DIAG]]

local function IsInsideScenarioStep(self, step, mapID)
    if self.IsInScenarioStep then return self:IsInScenarioStep(step, mapID) end
    if self.IsInScenarioMap then return self:IsInScenarioMap(mapID) end
    return C_Map.GetBestMapForUnit("player") == mapID or self:GetPlayerParentMapID() == mapID
end--[[APR_DIAG]]; IsInsideScenarioStep = APRTrace("APR-Core/utils/StepUtils.lua:702:IsInsideScenarioStep#29", IsInsideScenarioStep)--[[/APR_DIAG]]

--- Pick a routing target from a step zone list, preferring the current continent.
function APR:GetPreferredStepZone(step, fallbackMapID)
    local scenarioMapID, scenarioInfo = self:GetScenarioStepTarget(step)
    if scenarioInfo and scenarioInfo.zone then
        local isInsideScenario = IsInsideScenarioStep(self, step, scenarioMapID)

        if not isInsideScenario then
            return scenarioInfo.zone
        end
    end

    local zones = self:GetStepZoneList(step, fallbackMapID)
    if #zones == 0 then
        return nil
    end

    local playerContinent = self:GetContinent()
    for _, zone in ipairs(zones) do
        if self:GetContinent(zone) == playerContinent then
            return zone
        end
    end

    return zones[1]
end--[[APR_DIAG]]; APR.GetPreferredStepZone = APRTrace("APR-Core/utils/StepUtils.lua:709:APR:GetPreferredStepZone#30", APR.GetPreferredStepZone)--[[/APR_DIAG]]

local function IsCoordTable(value)
    return type(value) == "table" and value.x ~= nil and value.y ~= nil
end--[[APR_DIAG]]; IsCoordTable = APRTrace("APR-Core/utils/StepUtils.lua:734:IsCoordTable#31", IsCoordTable)--[[/APR_DIAG]]

local function ExtractCoord(entry)
    if IsCoordTable(entry) then
        return entry
    end

    if type(entry) == "table" and IsCoordTable(entry.Coord) then
        return entry.Coord
    end

    return nil
end--[[APR_DIAG]]; ExtractCoord = APRTrace("APR-Core/utils/StepUtils.lua:738:ExtractCoord#32", ExtractCoord)--[[/APR_DIAG]]

local function GetEntryZone(entry)
    if type(entry) ~= "table" then
        return nil
    end

    return entry.Zone or entry.zone or entry.mapID or entry.MapID or entry.uiMapID or entry.UiMapID
end--[[APR_DIAG]]; GetEntryZone = APRTrace("APR-Core/utils/StepUtils.lua:750:GetEntryZone#33", GetEntryZone)--[[/APR_DIAG]]

--- Resolve the best-matching zone id for the player, falling back to the preferred zone.
function APR:GetStepZoneForPlayer(step, fallbackMapID, zoneHint, zones)
    zones = zones or self:GetStepZoneList(step, fallbackMapID)
    if #zones == 0 then
        return nil
    end

    if zoneHint and self:Contains(zones, zoneHint) then
        return zoneHint
    end

    local currentMapID = C_Map.GetBestMapForUnit("player")
    if currentMapID and self:Contains(zones, currentMapID) then
        return currentMapID
    end

    local parentMapID = self:GetPlayerParentMapID()
    if parentMapID and self:Contains(zones, parentMapID) then
        return parentMapID
    end

    return self:GetPreferredStepZone(step, fallbackMapID)
end--[[APR_DIAG]]; APR.GetStepZoneForPlayer = APRTrace("APR-Core/utils/StepUtils.lua:759:APR:GetStepZoneForPlayer#34", APR.GetStepZoneForPlayer)--[[/APR_DIAG]]

--- Resolve the coordinate for a step, supporting multi-zone coordinates.
function APR:GetStepCoord(step, fallbackMapID, zoneHint)
    if not step then
        return nil
    end

    if self:IsTransportStep(step) then
        local trigger = step.ZoneStepTrigger
        if trigger.mapID and (C_Map.GetBestMapForUnit("player") == trigger.mapID
                or self:GetPlayerParentMapID() == trigger.mapID) then
            -- A flight already over its destination only needs to wait for landing.
            if trigger.x == nil or trigger.y == nil then return nil, trigger.mapID end
            return trigger, trigger.mapID
        end
    end

    local scenarioMapID, scenarioInfo = self:GetScenarioStepTarget(step)
    if scenarioInfo then
        local isInsideScenario = IsInsideScenarioStep(self, step, scenarioMapID)

        if not isInsideScenario then
            -- A locked or unresolved entrance must not fall back to interior
            -- coordinates interpreted in the outside world's coordinate space.
            return scenarioInfo.Coord, scenarioInfo.zone
        end
    end

    if IsCoordTable(step.Coord) then
        return step.Coord, nil
    end

    local coordsSource = step.Coords or step.Coord
    if type(coordsSource) ~= "table" then
        return nil
    end

    local zones = self:GetStepZoneList(step, fallbackMapID)
    local zoneId = self:GetStepZoneForPlayer(step, fallbackMapID, zoneHint, zones)
    local coord = nil

    if #coordsSource == 0 then
        if zoneId then
            coord = ExtractCoord(coordsSource[zoneId])
        end
        if not coord then
            for _, entry in pairs(coordsSource) do
                coord = ExtractCoord(entry)
                if coord then
                    break
                end
            end
        end
        return coord, zoneId
    end

    if zoneId then
        for _, entry in ipairs(coordsSource) do
            if GetEntryZone(entry) == zoneId then
                coord = ExtractCoord(entry)
                if coord then
                    break
                end
            end
        end
    end

    if not coord and zoneId and #zones > 0 then
        for index, zone in ipairs(zones) do
            if zone == zoneId then
                coord = ExtractCoord(coordsSource[index])
                if coord then
                    break
                end
            end
        end
    end

    if not coord then
        for _, entry in ipairs(coordsSource) do
            coord = ExtractCoord(entry)
            if coord then
                break
            end
        end
    end

    return coord, zoneId
end--[[APR_DIAG]]; APR.GetStepCoord = APRTrace("APR-Core/utils/StepUtils.lua:783:APR:GetStepCoord#35", APR.GetStepCoord)--[[/APR_DIAG]]

--- Determine if the provided quest id belongs to the current step.
function APR:IsARouteQuest(questId)
    local data = APRData and APRData[self.PlayerID]
    local step = data and self.ActiveRoute and self:GetStep(data[self.ActiveRoute])
    if not step or not questId then return false end

    -- Item-started quests can be offered during an objective step, outside the pickup pool.
    if questId == step.DropQuest or (step.DroppableQuest and questId == step.DroppableQuest.Qid) then
        return true
    end
    return self:IsQuestInPool(questId)
end--[[APR_DIAG]]; APR.IsARouteQuest = APRTrace("APR-Core/utils/StepUtils.lua:872:APR:IsARouteQuest#36", APR.IsARouteQuest)--[[/APR_DIAG]]

--- Quick check if the active step is a pickup step (for UI hints).
function APR:IsPickupStep()
    local step = self:GetCurrentStep()
    return step and (step.PickUp or step.PickUpDB) or false
end--[[APR_DIAG]]; APR.IsPickupStep = APRTrace("APR-Core/utils/StepUtils.lua:885:APR:IsPickupStep#37", APR.IsPickupStep)--[[/APR_DIAG]]

function APR:ExtractColorAndText(text)
    local colorHex, message = string.match(text, "^%[COLOR:#?(%x+)%]%s*(.+)")
    if colorHex then
        return colorHex, message
    else
        return nil, text
    end
end--[[APR_DIAG]]; APR.ExtractColorAndText = APRTrace("APR-Core/utils/StepUtils.lua:890:APR:ExtractColorAndText#38", APR.ExtractColorAndText)--[[/APR_DIAG]]

function APR:ResolveStepText(rawValue)
    if rawValue == nil then
        return nil, nil
    end

    local key = tostring(rawValue)
    local aprRCData = rawget(_G, "AprRCData")
    local globalText = rawget(_G, key)
    -- This field supplies no format arguments. Keep formatted globals with their callers.
    if type(globalText) ~= "string" or globalText == "" or
        globalText:find("%%[-+ #0]*%d*%.?%d*[cdiouxXeEfgGaAqs]") or
        globalText:find("%%%d+%$[-+ #0]*%d*%.?%d*[cdiouxXeEfgGaAqs]") or globalText:find("%%%%") then
        globalText = nil
    end
    local message = globalText or rawget(L, key) or
        (aprRCData and aprRCData.ExtraLineTexts and rawget(aprRCData.ExtraLineTexts, key)) or
        key

    if not message or message == "" then
        return nil, nil
    end

    local colorHex, formattedMessage = self:ExtractColorAndText(message)
    return formattedMessage, colorHex
end--[[APR_DIAG]]; APR.ResolveStepText = APRTrace("APR-Core/utils/StepUtils.lua:899:APR:ResolveStepText#39", APR.ResolveStepText)--[[/APR_DIAG]]

function APR:ResolveStepTextList(rawValue)
    local resolved = {}

    local function addResolvedText(value)
        local text, color = self:ResolveStepText(value)
        if text and text ~= "" then
            table.insert(resolved, {
                text = text,
                color = color,
            })
        end
    end--[[APR_DIAG]]; addResolvedText = APRTrace("APR-Core/utils/StepUtils.lua:928:addResolvedText#41", addResolvedText)--[[/APR_DIAG]]

    if type(rawValue) == "table" then
        for _, value in ipairs(rawValue) do
            addResolvedText(value)
        end
    else
        addResolvedText(rawValue)
    end

    return resolved
end--[[APR_DIAG]]; APR.ResolveStepTextList = APRTrace("APR-Core/utils/StepUtils.lua:925:APR:ResolveStepTextList#40", APR.ResolveStepTextList)--[[/APR_DIAG]]
